const delay=document.querySelector(".swiper.mySwiper").dataset.swiperDelay,swiper=new Swiper(".mySwiper",{grabCursor:!0,slidesPerView:1,autoHeight:!0,autoplay:{delay:Number(delay),disableOnInteraction:!1},navigation:{nextEl:".swiper-button-next",prevEl:".swiper-button-prev"},pagination:{el:".swiper-pagination",clickable:!0}});